drawViewmodel(ctx, W, H, dt) {
  const g = this.game;
  const p = g.player;
  const def = WEAPONS[p.current];
  if (p.current !== this.lastWeapon) { this.lastWeapon = p.current; this.weaponSwitchT = 0.25; }
  if (this.weaponSwitchT > 0) this.weaponSwitchT -= dt;

  const bobOn = this.settings.get('controls.viewBobbing');
  const speedK = Math.min(1, Math.hypot(p.vel[0], p.vel[2]) / 6.4);
  const bob = bobOn ? Math.sin(p.bobT * 9) * 6 * speedK : 0;
  const bobX = bobOn ? Math.cos(p.bobT * 4.5) * 5 * speedK : 0;
  const kick = g.recoil * 16;
  const raise = this.weaponSwitchT > 0 ? this.weaponSwitchT * 260 : 0;
  const reloadDip = p.reloadT > 0 ? Math.sin(Math.min(1, 1 - p.reloadT / (def.reloadTime || 1)) * Math.PI) * 70 : 0;
  // inertial sway lags the camera
  this.swayX += ((p._lastYaw !== undefined ? (p.yaw - p._lastYaw) : 0) * -260 - this.swayX) * Math.min(1, dt * 9);
  this.swayY += ((p._lastPitch !== undefined ? (p.pitch - p._lastPitch) : 0) * 200 - this.swayY) * Math.min(1, dt * 9);
  p._lastYaw = p.yaw;
  p._lastPitch = p.pitch;

  const img = this.vmSprites[p.current];
  const bx = W * 0.64 + bobX + this.swayX;
  const by = H * 0.82 + bob + kick + raise + reloadDip + this.swayY;
  const rot = -0.045 + g.recoil * -0.06 + (bobOn ? Math.sin(p.bobT * 4.5) * 0.008 * speedK : 0);
  let muzX, muzY;

  ctx.save();
  ctx.translate(bx, by);
  ctx.rotate(rot);
  if (img) {
    // Cycles-rendered sprite, muzzle facing right
    const scale = (def.melee ? 0.42 : def.scoped ? 0.62 : def.slot === 0 ? 0.55 : 0.45) * (W / 1280);
    const w = img.width * scale, h = img.height * scale;
    ctx.drawImage(img, -w * 0.42, -h * 0.52, w, h);
    muzX = w * 0.55; muzY = -h * 0.04;
  } else {
    // fallback silhouette while the sprite streams in
    const L = def.melee ? 60 : (def.scoped ? 170 : def.slot === 0 ? 130 : 85);
    ctx.fillStyle = '#15181f';
    ctx.fillRect(-30, 0, L, 26);
    ctx.fillStyle = '#3dffc8';
    ctx.fillRect(-30, 22, L, 2);
    muzX = L - 16; muzY = 8;
  }
  // muzzle flash anchored to the barrel tip, inside the gun transform
  if (this.flashT > 0) {
    this.flashT -= dt;
    if (!def.melee) {
      const a = this.flashT / 0.07;
      const r = 30 + Math.random() * 18;
      const grad = ctx.createRadialGradient(muzX, muzY, 2, muzX, muzY, r);
      grad.addColorStop(0, `rgba(255,245,200,${a})`);
      grad.addColorStop(0.35, `rgba(255,170,70,${a * 0.75})`);
      grad.addColorStop(1, 'rgba(255,120,30,0)');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(muzX, muzY, r, 0, Math.PI * 2);
      ctx.fill();
      // star spikes
      ctx.strokeStyle = `rgba(255,235,170,${a * 0.9})`;
      ctx.lineWidth = 2;
      ctx.beginPath();
      for (let i = 0; i < 4; i++) {
        const sa = (i / 4) * Math.PI * 2 + 0.4;
        ctx.moveTo(muzX, muzY);
        ctx.lineTo(muzX + Math.cos(sa) * r * 1.3, muzY + Math.sin(sa) * r * 0.8);
      }
      ctx.stroke();
    }
  }
  ctx.restore();
}
